mkdir -p notes
cat > notes/PRC-501.md <<'E'
# PRC-501 調査メモ
- 軌道: T2（会員価格＝金額の計算、4 箇所に同じ式）。戻せない操作なし（push は行わない）。
- 完了の条件: 会員価格が 10% 引きの切り捨てで、999 → 899 になる（bin/price, bin/quote, lib/invoice.sh, lib/statement.sh すべて）。
- 原因: ee322d6 "tidy up rounding" で `x*90/100` が `(x*90+99)/100`（切り上げ）に変わった。
- 同じ式の箇所（grep "90 + 99"）: bin/price, bin/quote, lib/invoice.sh, lib/statement.sh（main の 02a8d9b で追加、Issue に無い）。base は HEAD=ee322d6、main=02a8d9b、merge-base=ee322d6。main を branch に merge 済み。
- 設計: 解は 1 つ。元の `x*90/100`（整数除算＝切り捨て）に戻す。共通関数化は範囲外。
- 既存テストは 500/1000 のみで、端数が出ない値なので切り上げを検出できなかった。
- 品質トレードオフ: 4 箇所に式が重複（今回は触らない、別チケット提案）。
E
cat > tests/price_test.sh <<'E'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(source lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
[ "$(bash lib/statement.sh 999)" = "statement member 899" ] || { echo "statement 999"; fail=1; }
exit $fail
E
bash scripts/verify.sh; echo "exit=$?"
